/* Compact hospital identity */
.brand{gap:12px;align-items:center;padding:4px 9px 20px}.brand .hospital-symbol{width:48px;height:48px;border-radius:10px;box-shadow:none;background:transparent;padding:0;flex-shrink:0}.brand .hospital-logo{object-fit:contain;border-radius:0}.brand-copy strong{font-size:19px;font-weight:600;letter-spacing:.2px;line-height:1.35}.brand-copy small{font-size:11px;margin-top:4px;color:#887592;line-height:1.5}.hospital-footer{display:flex;align-items:center;justify-content:space-between;gap:9px 24px;padding:18px 0 0;margin-top:28px;background:transparent;border:0;border-top:1px solid #e9e1ee;border-radius:0;box-shadow:none;font-size:10px;color:#8b7b95}.footer-hospital-name{font-size:11px;line-height:1.8;color:#796b83;max-width:100%}.footer-credits{display:flex;align-items:center;justify-content:flex-end;gap:4px 16px;flex-wrap:wrap;font-size:10px;text-align:right}.footer-credits span{line-height:1.8}.sidebar-collapsed .brand .hospital-symbol{width:42px;height:42px;padding:0}.sidebar-collapsed .brand{padding:0 0 18px}@media(max-width:1000px){.hospital-footer{align-items:flex-start;flex-direction:column}.footer-credits{text-align:left;justify-content:flex-start}}@media(max-width:760px){.brand{padding:4px 7px 13px}.sidebar-collapsed .brand{padding:0}.hospital-footer{padding:16px 0 0}}

#monthly{display:block;height:auto;min-height:210px;overflow-x:auto;padding:8px 0 0;border-bottom:0}
.monthly-bars{display:flex;align-items:flex-end;gap:16px;min-width:100%;width:max-content;height:200px;border-bottom:1px solid var(--stroke);padding:10px 6px 0}
.monthly-bars .barwrap{min-width:55px;flex:1}
.monthly-bars .bar{width:100%;max-width:90px;margin:4px auto 0}
.monthly-bars .barwrap span{white-space:nowrap}

.lab-patient-row{cursor:pointer}.lab-patient-row:hover{background:var(--teal2)}

/* Hospital identity: full-width name with the navigation control on the edge. */
.sidebar-heading{position:relative;display:flex;align-items:center;justify-content:center;min-height:48px;margin:0 0 16px;padding:0 2px;flex-shrink:0}
.sidebar-hospital-name{min-width:0;max-width:100%;text-align:center;color:#624774;font-weight:600;line-height:1.7}
.sidebar-hospital-name span{display:block;white-space:nowrap;font-size:12px;letter-spacing:-.15px}
.sidebar-hospital-name span+span{font-size:11px;font-weight:400;color:#897493;letter-spacing:0;margin-top:1px}
.sidebar-heading>.sidebar-toggle{position:absolute;right:-30px;top:8px;width:28px;height:28px;border-radius:50%;background:#fff;border:1px solid #e6d9ef;color:#9370aa;box-shadow:0 2px 7px #6345780d;z-index:2}
.side .brand{justify-content:center;padding:0 3px 18px;gap:12px}
.side .brand-copy strong{font-size:19px;line-height:1.3}
.side .brand-copy small{font-size:10px;margin-top:3px}
.sidebar-collapsed .sidebar-hospital-name{display:none}
.sidebar-collapsed .sidebar-heading{min-height:28px;margin-bottom:14px;padding:0}
.sidebar-collapsed .sidebar-heading>.sidebar-toggle{position:static}
.sidebar-collapsed .side .brand{padding:0 0 18px}
@media(max-width:760px){.sidebar-heading{justify-content:flex-start;margin-bottom:12px;padding-right:40px}.sidebar-hospital-name{text-align:left}.sidebar-heading>.sidebar-toggle{right:0;top:6px}.sidebar-collapsed .sidebar-heading{justify-content:flex-end;margin-bottom:8px;padding:0}.side .brand{justify-content:flex-start;padding-left:2px}}
@media print{.sidebar-heading>.sidebar-toggle{display:none}}
/* Dashboard summary */
#dashboard .cards>.kpi{display:flex;flex-direction:column;min-height:180px;text-align:left}
#dashboard .cards>.kpi>b{flex:1;display:grid;place-items:center;text-align:center;min-height:86px;font-size:42px;line-height:1.2;font-variant-numeric:tabular-nums;width:100%}
#dashboard .cards>.kpi>small{display:block;text-align:center;line-height:1.7}
.overview-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:20px 0}
.overview-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:8px 0 16px}
.overview-metric{padding:16px 8px;background:#f8f5fc;border:1px solid var(--stroke);border-radius:12px;text-align:center}
.overview-metric b{display:block;font-size:27px;color:#8756ac;font-variant-numeric:tabular-nums}
.overview-metric span{font-size:11px;color:var(--sub)}
.overview-row{padding:12px 0;border-bottom:1px solid var(--stroke)}
