<script>
'use strict';let currentPage='dashboard',activeTab=0,activeCase=0,imported=false;
let csrfToken=<?php echo json_encode($_SESSION['csrf']); ?>;const manualDrafts={};
const FIELD_CATALOG=<?php echo json_encode(array_map(static fn($f)=>array_diff_key($f,['sql'=>true]), reportFields()),JSON_UNESCAPED_UNICODE); ?>;
const DATA={main:[],labs:[],complications:[],vaccines:[],lab_results:[]};
let registrySearchActive=false;let detailData=DATA,registrySearchData=null,registrySearchStatus="",registrySearchTimer,registrySearchVersion=0;
const titles={dashboard:'ภาพรวมการคลอด',registry:'ทะเบียนผู้คลอด',detail:'เวชระเบียน EMR',labs:'ผลตรวจทางห้องปฏิบัติการ',complications:'ภาวะแทรกซ้อน',vaccines:'วัคซีน',import:'สถานะเชื่อมต่อ HOSxP',risk:'คัดกรองทารกเสี่ยง',dictionary:'โครงสร้างข้อมูล'};
function go(page){document.body.classList.toggle('home-mode',page==='dashboard');currentPage=page;document.getElementById('live-status').classList.toggle('hide',page==='risk');document.querySelector('.topbar small').textContent=page==='risk'?'คัดกรองตามวันเกิดทารก • ข้อมูล HOSxP':'ระบบติดตามข้อมูลห้องคลอด • ช่วงวันที่รับไว้รักษาของมารดา';document.querySelectorAll('.page').forEach(x=>x.classList.toggle('hide',x.id!==page));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.getElementById('top-title').textContent=titles[page];if(page==='risk'&&!riskLoaded)loadInfantRisk();if(page==='detail')renderDetail();if(page==='registry')renderRegistry();if(['labs','vaccines','complications'].includes(page))renderLinked();window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('.nav[data-page]').forEach(x=>x.addEventListener('click',()=>go(x.dataset.page)));
const H=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const val=(r,k)=>r?.[k]??'';function fieldDisplayValue(r,k){
 const v=val(r,k),text=String(v).trim();
 if(FIELD_CATALOG.some(f=>f.label===k&&f.type==='time')&&/^\d{2}:\d{2}/.test(text))return text.slice(0,5).replace(':','.');
 if(k==='เพศทารก'||k==='เพศทารก (รหัส)'){
  const sex=text||String(val(r,'เพศทารก (รหัส)')).trim();
  return ({'1':'ชาย','2':'หญิง','ช':'ชาย','ญ':'หญิง','ชาย':'ชาย','หญิง':'หญิง'})[sex]||'ระบุไม่ได้';
 }
 if(k.endsWith('(รหัส)')&&['Y','N'].includes(text.toUpperCase()))return text.toUpperCase()==='Y'?'Yes':'No';
 return v;
}
const display=(r,k)=>{const v=fieldDisplayValue(r,k);return v===''||v===null?'<span class="muted">ไม่ระบุ</span>':H(v)};const n=x=>Number(x);const date=r=>String(val(r,'วันที่คลอด')).slice(0,10);const admitDate=r=>String(val(r,'วันที่ Admit')).slice(0,10);const inRange=r=>admitDate(r)>=(document.getElementById('from').value||'0000')&&admitDate(r)<=(document.getElementById('to').value||'9999');const filtered=()=>DATA.main.filter(inRange);const pct=(k,t)=>t?Math.round(k/t*100):0;function bangkokToday(now=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const part=type=>parts.find(p=>p.type===type).value;return part('year')+'-'+part('month')+'-'+part('day')}
function setTodayDates(){const today=bangkokToday();document.getElementById('from').value=today;document.getElementById('to').value=today}
function resetDates(){setTodayDates();loadLive()}
function deliveryAdmissionRows(rows){return rows.filter(r=>Number(r._delivery_admission)===1)}
function monthlyBarChart(by){
 const keys=Object.keys(by).sort();
 if(!keys.length)return '<div class="empty" style="width:100%">ไม่มีข้อมูลในช่วงวันที่เลือก</div>';
 const colors=['#b74786','#8c6ac8','#3299b5','#d38a36','#489e78','#cf6c70','#647bc2','#a08042','#5d9d9b','#af72a2','#73994c','#b87952'];
 const max=Math.max(1,...Object.values(by));
 return '<div class="monthly-bars" role="img" aria-label="'+H('จำนวนทารกคลอดรายเดือน '+keys.map(k=>(Number(k.slice(5)))+'/'+(Number(k.slice(0,4))+543)+' '+by[k]+' ราย').join(', '))+'">'+keys.map(k=>{const month=Number(k.slice(5)),label=String(month).padStart(2,'0')+'/'+(Number(k.slice(0,4))+543);return '<div class="barwrap"><b class="mini">'+by[k]+' ราย</b><div class="bar" style="height:'+Math.max(4,by[k]/max*145)+'px;background:'+colors[month-1]+'" title="'+H(label+' : '+by[k]+' ราย')+'"></div><span>'+H(label)+'</span></div>'}).join('')+'</div>';
}
function overviewBreakdown(items,total){
 return items.map(([label,count])=>'<div class="overview-row"><div class="lineitem"><span>'+H(label)+'</span><b>'+count.toLocaleString('th-TH')+' ราย'+(total?' ('+pct(count,total)+'%)':'')+'</b></div><div class="progress"><div style="width:'+pct(count,total)+'%"></div></div></div>').join('');
}
function renderOverviewDetails(all,rows){
 const newborns=DATA.newborns||[],loaded=Number.isInteger(DATA.newborn_admissions);
 const linked=newborns.filter(r=>r.mother_an).length,conflict=newborns.filter(r=>r.relationship_status==='ข้อมูล AN มารดาขัดแย้ง').length;
 document.getElementById('overview-family').innerHTML=loaded?'<div class="overview-metrics">'+[['เชื่อมแม่ได้',linked],['ยังไม่พบ AN แม่',newborns.length-linked-conflict],['AN แม่ขัดแย้ง',conflict]].map(([label,count])=>'<div class="overview-metric"><b>'+count+'</b><span>'+label+'</span></div>').join('')+'</div><p class="mini">นับ AN ลูกไม่ซ้ำตามวัน Admit ทารก · แม่หนึ่งคนมีลูกได้หลายคน</p><button class="btn small" onclick="openNewbornFamilies()">ดู AN แม่–ลูก</button>':'<div class="empty">ยังไม่มีข้อมูลที่โหลดสำเร็จ</div>';
 const methods=new Map();rows.forEach(r=>{const name=String(val(r,'วิธีคลอดทารก')).trim()||'ยังไม่ระบุวิธีคลอด';methods.set(name,(methods.get(name)||0)+1)});
 document.getElementById('overview-delivery').innerHTML=rows.length?overviewBreakdown([...methods].sort((a,b)=>b[1]-a[1]),rows.length)+'<p class="mini">ต่อระเบียนทารกของมารดาที่ Admit ในช่วงวันที่เลือก</p>':'<div class="empty">ไม่มีระเบียนทารกในช่วงวันที่เลือก</div>';
 const missing=key=>rows.filter(r=>String(val(r,key)).trim()==='').length;
 const noId=rows.filter(r=>!String(val(r,'HN ทารก')).trim()&&!String(val(r,'AN ทารก')).trim()).length;
 const unknownSex=rows.filter(r=>!['ชาย','หญิง'].includes(String(fieldDisplayValue(r,'เพศทารก')).trim())).length;
 const invalidWeight=rows.filter(r=>val(r,'น้ำหนักทารก กรัม')===''||!Number.isFinite(Number(val(r,'น้ำหนักทารก กรัม')))||Number(val(r,'น้ำหนักทารก กรัม'))<=0).length;
 document.getElementById('overview-review').innerHTML=rows.length?overviewBreakdown([['ยังไม่มีทั้ง HN และ AN ลูก',noId],['เพศไม่ระบุ / ระบุไม่ได้',unknownSex],['น้ำหนักว่างหรือใช้คำนวณไม่ได้',invalidWeight],['ยังไม่มี APGAR นาทีที่ 5',missing('APGAR 5 นาที')]],rows.length)+'<p class="mini">หนึ่งระเบียนอาจอยู่ได้หลายรายการ · ค่าว่างไม่ถือว่าปกติ</p>':'<div class="empty">ไม่มีระเบียนทารกให้ตรวจสอบ</div>';
 const unavailable=all.filter(r=>r._supplement_available===false).length;
 document.getElementById('overview-supplement').innerHTML=!loaded?'<div class="empty">รอโหลดข้อมูลสำเร็จ</div>':!all.length?'<div class="empty">ไม่มีระเบียนมารดาในช่วงวันที่เลือก</div>':unavailable?'<div class="privacy">ฐานข้อมูลเสริมไม่พร้อมใช้งาน '+unavailable+' ระเบียน · ยังแก้ไขและบันทึกไม่ได้</div>':'<div class="note">โหลดฐานข้อมูลเสริมสำเร็จ · พร้อมกรอกและบันทึก</div><div class="overview-metrics">'+[['ระเบียนทั้งหมด',all.length],['มีข้อมูลกรอกเสริม',all.filter(r=>Object.keys(r._manual||{}).length>0).length],['มีประวัติแก้ไข',all.filter(r=>Number(r._version)>0).length]].map(([label,count])=>'<div class="overview-metric"><b>'+count+'</b><span>'+label+'</span></div>').join('')+'</div>';
}
function isLowBirthWeight(r){const v=val(r,'น้ำหนักทารก กรัม'),n=Number(v);return String(v).trim()!==''&&Number.isFinite(n)&&n>0&&n<2500}
function isLowApgar5(r){const v=val(r,'APGAR 5 นาที'),n=Number(v);return String(v).trim()!==''&&Number.isInteger(n)&&n>=0&&n<7}
function renderDashboard(){let all=deliveryAdmissionRows(filtered()),rows=all.filter(r=>r._infant_id!==null),mom=new Set(all.map(r=>val(r,'AN มารดา')).filter(Boolean)).size;let low=rows.filter(r=>isLowBirthWeight(r)).length;let ap=rows.filter(r=>isLowApgar5(r)).length;[['k-baby',DATA.newborn_admissions??'—'],['k-mom',mom],['k-low',low],['k-apgar',ap]].forEach(([id,v])=>document.getElementById(id).textContent=v.toLocaleString('th-TH'));
renderOverviewDetails(all,rows);
let fields=[['HN ทารก','q-hn','bar-hn'],['น้ำหนักทารก กรัม','q-weight','bar-weight'],['APGAR 5 นาที','q-apgar','bar-apgar']];fields.forEach(([key,label,bar])=>{let count=rows.filter(r=>String(val(r,key)).trim()!==''||(key==='HN ทารก'&&String(val(r,'AN ทารก')).trim()!=='')).length;document.getElementById(label).textContent=`${count}/${rows.length} (${pct(count,rows.length)}%)`;document.getElementById(bar).style.width=pct(count,rows.length)+'%'});
let by={};rows.forEach(r=>{let d=date(r);if(/^\d{4}-\d{2}-\d{2}$/.test(d)){let key=d.slice(0,7);by[key]=(by[key]||0)+1}});document.getElementById('monthly').innerHTML=monthlyBarChart(by);document.getElementById('recent').innerHTML=rows.slice().sort((a,b)=>(date(b)+val(b,'เวลาคลอด')).localeCompare(date(a)+val(a,'เวลาคลอด'))).slice(0,6).map(r=>`<tr><td>${display(r,'วันที่คลอด')} ${display(r,'เวลาคลอด')}</td><td>${display(r,'AN มารดา')}</td><td>${display(r,'HN ทารก')}<div class="mini">AN ${H(val(r,'AN ทารก')||'ยังไม่ระบุ')}</div></td><td>${display(r,'น้ำหนักทารก กรัม')}</td><td>${[1,5,10].map(x=>H(val(r,'APGAR '+x+' นาที')===''?'-':val(r,'APGAR '+x+' นาที'))).join(' / ')}</td><td><button class="links" onclick="openCase(${DATA.main.indexOf(r)})">ดูรายละเอียด</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">ไม่มีข้อมูล</td></tr>'}
function resetRegistrySearch(){document.getElementById('search').value='';document.getElementById('registry-filter').value='all';searchRegistry()}
function searchRegistry(){
 document.getElementById('registry-filter').value='all';
 registrySearchActive=true;
 const query=document.getElementById('search').value.trim();
 const version=++registrySearchVersion;
 clearTimeout(registrySearchTimer);
 registrySearchData=null;
 registrySearchStatus='กำลังค้นหา…';
 renderRegistry();
 const basis='all';
 const from=document.getElementById('from').value,to=document.getElementById('to').value;
 registrySearchTimer=setTimeout(async()=>{
  try{
   const res=await fetch('api.php?'+new URLSearchParams({scope:'search',q:query,basis,from,to}),{cache:'no-store',headers:{Accept:'application/json'}});
   const payload=await res.json();
   if(version!==registrySearchVersion)return;
   if(res.status===401){window.location.href='login.php';return}
   if(!res.ok||!payload.ok)throw Error(payload.error||'ค้นหาไม่สำเร็จ');
   registrySearchData=payload.data;
   csrfToken=payload.csrf;
   registrySearchStatus=(payload.warnings||[]).join(' ');
  }catch(err){
   if(version!==registrySearchVersion)return;
   registrySearchStatus=err.message;
  }
  renderRegistry();
 },300);
}
function openNewbornFamilies(){
 document.getElementById('newborn-family-rows').innerHTML=(DATA.newborns||[]).map(r=>'<tr><td>'+H(r.regdate||'')+'</td><td>'+H(r.hn||'')+'</td><td>'+H(r.an||'')+'</td><td>'+H(r.mother_an||'ไม่ระบุ')+'</td><td>'+H(r.relationship_status||'')+'</td></tr>').join('')||'<tr><td colspan="5" class="empty">ไม่พบข้อมูลในช่วงวันที่เลือก</td></tr>';
 document.getElementById('newborn-families').showModal();
}
function openDashboardRecords(group){
 registrySearchActive=false;
 document.getElementById('search').value='';
 clearTimeout(registrySearchTimer);++registrySearchVersion;
 registrySearchData=null;registrySearchStatus='';
 document.getElementById('registry-filter').value=group;
 go('registry');
}
function registryRows(){
 const searching=registrySearchActive;
 let rows=deliveryAdmissionRows(searching?(registrySearchData?.main||[]):filtered());
 const group=document.getElementById('registry-filter').value;
 if(group==='baby')rows=rows.filter(r=>r._infant_id!==null);
 if(group==='low')rows=rows.filter(r=>r._infant_id!==null&&isLowBirthWeight(r));
 if(group==='apgar')rows=rows.filter(r=>r._infant_id!==null&&isLowApgar5(r));
 if(group==='mom'){const seen=new Set();rows=rows.filter(r=>{const an=val(r,'AN มารดา');if(!an||seen.has(an))return false;seen.add(an);return true})}
 return rows.slice();
}
