 const searching=registrySearchActive;
 const source=searching?registrySearchData:DATA;
 const rows=registryRows();
 document.getElementById('registry-search-status').textContent=registrySearchStatus;
 rows.sort((a,b)=>(date(a)+val(a,'เวลาคลอด')).localeCompare(date(b)+val(b,'เวลาคลอด'))*(document.getElementById('registry-sort').value==='new'?-1:1));document.getElementById('totalrows').textContent=`${rows.length} รายการ`;document.getElementById('registry-table').closest('table').querySelector('thead').innerHTML='<tr>'+['ลำดับที่','วันที่ / เวลาเกิด','HN / AN มารดา','มารดา','HN / AN ทารก','GA','วิธีการคลอด','ชื่อคนทำคลอด','เพศทารก','น้ำหนัก','APGAR 1 / 5 / 10','น้ำหนักรก (กรัม)','วันที่แจ้งเกิด','ผู้แจ้งเกิด / เบอร์โทร','ดูข้อมูล'].map(x=>'<th>'+H(x)+'</th>').join('')+'</tr>';
 document.getElementById('registry-table').innerHTML=rows.map((r,i)=>`<tr class="registry-risk-${recordedRisk(r).kind}"><td>${i+1}</td><td>${display(r,'วันที่คลอด')} ${display(r,'เวลาคลอด')}</td><td>HN ${display(r,'HN มารดา')}<br>AN ${display(r,'AN มารดา')}</td><td>${display(r,'ชื่อ-สกุลมารดา')} ${riskBadge(r)}</td><td>HN ${display(r,'HN ทารก')}<br>AN ${display(r,'AN ทารก')}</td>${['GA ทารก','วิธีคลอดทารก','ชื่อผู้ทำคลอด','เพศทารก','น้ำหนักทารก กรัม'].map(k=>'<td>'+display(r,k)+'</td>').join('')}<td>${[1,5,10].map(m=>display(r,'APGAR '+m+' นาที')).join(' / ')}</td>${['น้ำหนักรก (กรัม)','วันที่แจ้งเกิด','ชื่อผู้แจ้งเกิดและเบอร์โทร'].map(k=>'<td>'+display(r,k)+'</td>').join('')}<td><button class="btn small ghost" onclick="openCase(${source.main.indexOf(r)},${searching})">เปิดดู</button></td></tr>`).join('')||'<tr><td colspan="15" class="empty">'+H(registrySearchStatus||'ไม่พบข้อมูล')+'</td></tr>'}

const tabs=[0,1,2,3,4].map(tab=>[FIELD_CATALOG.filter(f=>f.tab===tab).map(f=>f.label)]);

const emrTabTitles=['ข้อมูลมารดา / Admit','ประวัติการตั้งครรภ์ / ANC','การคลอดและข้อมูลทารก','APGAR และการช่วยเหลือ','การดูแลและจำหน่าย','ผลตรวจทางห้องปฏิบัติการ','ภาวะแทรกซ้อนมารดาและทารก'];
const manualSaving=new Set();

const thaiMonths=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
let thaiCalendarTarget='',thaiCalendarYear=0,thaiCalendarMonth=0;
function formatThaiInput(iso){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(iso||'');return m?m[3]+'/'+m[2]+'/'+(+m[1]+543):''}
function parseThaiInput(text){
 const cleaned=text.trim().replace(/[๐-๙]/g,c=>String(c.charCodeAt(0)-3664));const m=/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/.exec(cleaned);
 if(!m)return null;const year=+m[3]-543,month=+m[2],day=+m[1];if(year<1000||year>9456)return null;
 const d=new Date(Date.UTC(year,month-1,day));if(d.getUTCFullYear()!==year||d.getUTCMonth()!==month-1||d.getUTCDate()!==day)return null;
 return String(year).padStart(4,'0')+'-'+String(month).padStart(2,'0')+'-'+String(day).padStart(2,'0');
}
function syncThaiDateInputs(){for(const id of ['from','to','emr-from','emr-to','risk-from','risk-to']){const source=document.getElementById(id),text=document.getElementById(id+'-thai');text.value=formatThaiInput(source.value);text.disabled=source.disabled;document.getElementById(id+'-calendar').disabled=source.disabled;text.setCustomValidity('')}}
function applyThaiDate(id,iso){document.getElementById(id).value=iso;document.getElementById(id+'-thai').value=formatThaiInput(iso);if(id.startsWith('registry-'))searchRegistry();else if(id.startsWith('risk-'))loadInfantRisk();else if(id.startsWith('emr-'))changeEmrPeriod();else loadLive()}
function commitThaiDate(id){const input=document.getElementById(id+'-thai'),iso=parseThaiInput(input.value);input.setCustomValidity(iso?'':'กรอกวันที่เป็น วัน/เดือน/ปี พ.ศ. เช่น 05/11/2569');if(!iso){input.reportValidity();return}applyThaiDate(id,iso)}
function openThaiCalendar(id){
 if(document.getElementById(id).disabled)return;thaiCalendarTarget=id;
 const iso=document.getElementById(id).value;const parts=/^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);const now=new Date();thaiCalendarYear=parts?+parts[1]:now.getFullYear();thaiCalendarMonth=parts?+parts[2]-1:now.getMonth();renderThaiCalendar();document.getElementById('thai-calendar').showModal();
}
function moveThaiMonth(step){const date=new Date(Date.UTC(thaiCalendarYear,thaiCalendarMonth+step,1));if(date.getUTCFullYear()<1000||date.getUTCFullYear()>9456)return;thaiCalendarYear=date.getUTCFullYear();thaiCalendarMonth=date.getUTCMonth();renderThaiCalendar()}
function changeThaiCalendarYear(value){const year=Number(value)-543;if(!Number.isInteger(year)||year<1000||year>9456)return;thaiCalendarYear=year;renderThaiCalendar()}
function selectThaiDay(day){const iso=String(thaiCalendarYear).padStart(4,'0')+'-'+String(thaiCalendarMonth+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');document.getElementById('thai-calendar').close();applyThaiDate(thaiCalendarTarget,iso)}
function renderThaiCalendar(){
 const first=new Date(Date.UTC(thaiCalendarYear,thaiCalendarMonth,1)).getUTCDay();const days=new Date(Date.UTC(thaiCalendarYear,thaiCalendarMonth+1,0)).getUTCDate();const selected=document.getElementById(thaiCalendarTarget).value;const now=new Date();
 let grid=['อา','จ','อ','พ','พฤ','ศ','ส'].map(d=>'<small>'+d+'</small>').join('')+'<span></span>'.repeat(first);
 for(let day=1;day<=days;day++){const iso=thaiCalendarYear+'-'+String(thaiCalendarMonth+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');const today=thaiCalendarYear===now.getFullYear()&&thaiCalendarMonth===now.getMonth()&&day===now.getDate();grid+='<button type="button" class="thai-calendar-day '+(selected===iso?'selected ':'')+(today?'today':'')+'" aria-label="'+day+' '+thaiMonths[thaiCalendarMonth]+' '+(thaiCalendarYear+543)+'" onclick="selectThaiDay('+day+')">'+day+'</button>'}
 document.getElementById('thai-calendar-content').innerHTML='<div class="thai-calendar-head"><button type="button" class="btn small" aria-label="เดือนก่อน" onclick="moveThaiMonth(-1)">‹</button><select class="input" aria-label="เดือน" onchange="thaiCalendarMonth=+this.value;renderThaiCalendar()">'+thaiMonths.map((name,i)=>'<option value="'+i+'" '+(i===thaiCalendarMonth?'selected':'')+'>'+name+'</option>').join('')+'</select><input class="input" type="number" aria-label="ปี พ.ศ." min="1543" max="9999" value="'+(thaiCalendarYear+543)+'" onchange="changeThaiCalendarYear(this.value)"><button type="button" class="btn small" aria-label="เดือนถัดไป" onclick="moveThaiMonth(1)">›</button></div><div class="thai-calendar-grid">'+grid+'</div><div class="thai-calendar-footer"><span class="mini">วัน / เดือน / ปี พ.ศ.</span><button type="button" class="btn small" onclick="document.getElementById(\'thai-calendar\').close()">ปิด</button></div>';
}

let emrRequestId=0;
async function changeEmrScope(){
 const requestId=++emrRequestId,ward=document.getElementById('emr-scope').value==='ward';
 document.getElementById('emr-from').disabled=ward;document.getElementById('emr-to').disabled=ward;
 if(!ward){detailData=DATA;activeCase=0;renderDetail();return}
 try{
  const res=await fetch('api.php?'+new URLSearchParams({scope:'ward',from:document.getElementById('from').value,to:document.getElementById('to').value}),{cache:'no-store',headers:{Accept:'application/json'}});
  const payload=await res.json();if(requestId!==emrRequestId)return;
  if(res.status===401){window.location.href='login.php';return}
  if(!res.ok||!payload.ok)throw Error(payload.error||'โหลดข้อมูลไม่สำเร็จ');
  detailData=payload.data;csrfToken=payload.csrf;activeCase=0;renderDetail();
 }catch(error){if(requestId!==emrRequestId)return;detailData={main:[],labs:[],lab_results:[],complications:[],vaccines:[]};renderDetail();document.getElementById('case-fields').textContent=error.message}
}
function changeEmrPeriod(){document.getElementById('from').value=document.getElementById('emr-from').value;document.getElementById('to').value=document.getElementById('emr-to').value;loadLive()}


let riskLoaded=false,riskRequestId=0,riskData={primary:[],newborns:[],monthly:[]};
async function loadInfantRisk(){
 const request=++riskRequestId;syncThaiDateInputs();riskLoaded=true;riskData={primary:[],newborns:[],monthly:[]};renderInfantRisk();document.getElementById('risk-message').textContent='กำลังอ่านข้อมูลคัดกรอง…';
 try{const from=document.getElementById('risk-from').value,to=document.getElementById('risk-to').value;const res=await fetch('risk.php?from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to),{credentials:'same-origin',cache:'no-store'});const data=await res.json();if(request!==riskRequestId)return;if(res.status===401){location.href='login.php';return}if(!res.ok||!data.ok)throw Error(data.error||'โหลดข้อมูลไม่สำเร็จ');riskData=data;renderInfantRisk();document.getElementById('risk-message').textContent='ข้อมูลวันเกิด '+formatThaiInput(from)+' – '+formatThaiInput(to)+' · อัปเดต '+new Date().toLocaleString('th-TH');}
 catch(error){if(request!==riskRequestId)return;riskLoaded=false;document.getElementById('risk-message').textContent=error.message;}
}
function renderInfantRisk(){
 const source=document.getElementById('risk-source').value,filter=document.getElementById('risk-filter').value,q=document.getElementById('risk-search').value.trim().toLowerCase();
 document.getElementById('risk-filter').querySelector('option[value="10"]').disabled=source==='newborns';if(source==='newborns'&&filter==='10')document.getElementById('risk-filter').value='all';const selectedFilter=document.getElementById('risk-filter').value;
 const rows=riskData[source].filter(r=>(selectedFilter==='all'||(selectedFilter==='weight'?r._risk.weight_group:r._risk.reasons.includes('APGAR '+selectedFilter+' นาที < 7')))&&Object.values(r).some(v=>typeof v!=='object'&&String(v??'').toLowerCase().includes(q)));
 const primary=riskData.primary;const cards=[['เข้าเกณฑ์ทะเบียนคลอด',primary.length],['เข้าเกณฑ์ ipt_newborn',riskData.newborns.length],['น้ำหนักต่ำกว่า 2,500 กรัม',primary.filter(r=>r._risk.weight_group).length],['APGAR นาทีที่ 5 < 7',primary.filter(r=>r._risk.reasons.includes('APGAR 5 นาที < 7')).length]];
 document.getElementById('risk-cards').innerHTML=cards.map(([label,count])=>'<div class="kpi"><div class="cap">'+label+'</div><b>'+count.toLocaleString('th-TH')+'</b><small>'+(label.includes('ipt_newborn')?'แยกแหล่งข้อมูล ไม่รวมกับทะเบียนคลอด':'จากทะเบียนคลอดที่เข้าเกณฑ์')+'</small></div>').join('');document.getElementById('risk-count').textContent=rows.length+' รายการในแหล่งที่เลือก';
 document.getElementById('risk-rows').innerHTML=rows.map(r=>{
 const main=source==='primary',birth=main?val(r,'วันที่คลอด'):r.born_date,motherAn=main?val(r,'AN มารดา'):r.mother_an,motherHn=main?val(r,'HN มารดา'):r.mother_hn,infantAn=main?val(r,'AN ทารก'):r.newborn_an;
 const scores=main?[r['APGAR 1 นาที'],r['APGAR 5 นาที'],r['APGAR 10 นาที']]:[r.apgar1,r.apgar2,null];
 const keys=main?['วิธีคลอดทารก','สถานที่คลอด','APGAR 1 นาที hr','APGAR 1 นาที rr','APGAR 1 นาที reflex','APGAR 1 นาที tone','APGAR 1 นาที color','APGAR 5 นาที hr','APGAR 5 นาที rr','APGAR 5 นาที reflex','APGAR 5 นาที tone','APGAR 5 นาที color','Birth asphyxia (รหัส)','รายละเอียด Birth asphyxia','ICD10 ทารก','PPV (รหัส)','ET tube (รหัส)','Chest compression (รหัส)','Oxygen box (รหัส)','Narcan (รหัส)','ให้นม (รหัส)','Vitamin K (รหัส)','HBV (รหัส)','ยาป้ายตา (รหัส)','คัดกรองไทรอยด์ (รหัส)','ผล TSH','ชื่อผู้ทำคลอด']:['condition1','condition2','dead','death_cause','note','doctor'];
 const label={condition1:'ภาวะแรกเกิด 1',condition2:'ภาวะแรกเกิด 2',dead:'เสียชีวิต (รหัส)',death_cause:'สาเหตุเสียชีวิต',note:'หมายเหตุ',doctor:'ผู้บันทึก newborn'};
 return '<tr><td>'+H(formatThaiInput(String(birth||'').slice(0,10))||'ไม่ระบุ')+'<br><small>'+H(main?val(r,'เวลาคลอด'):r.born_time||'')+'</small></td><td>'+H(main?val(r,'ชื่อ-สกุลมารดา'):'')+'<br>HN '+H(motherHn||'—')+'<br>AN '+H(motherAn||'—')+'</td><td>AN '+H(infantAn||'ไม่ระบุ')+(main?'<br>HN '+H(val(r,'HN ทารก')||'ไม่ระบุ')+'<br>ลำดับ '+H(val(r,'ลำดับทารก')):'')+'</td><td>'+(main?'GA '+H(val(r,'GA ทารก')||'ไม่ระบุ')+' wk<br>':'')+H((main?r['น้ำหนักทารก กรัม']:r.birth_weight)??'ไม่ระบุ')+' g</td><td>'+scores.map(v=>v===null||v===undefined||v===''?'—':H(v)).join(' / ')+'</td><td>'+r._risk.reasons.map(reason=>'<span class="pill red">'+H(reason)+'</span>').join(' ')+'</td><td><details class="lab-details"><summary>ดูรายละเอียด</summary><dl>'+keys.map(k=>'<dt>'+H(label[k]||k)+'</dt><dd>'+display(r,k)+'</dd>').join('')+'</dl></details></td></tr>';
 }).join('')||'<tr><td colspan="7" class="empty">ไม่พบรายการที่เข้าเกณฑ์ในตัวกรองนี้</td></tr>';
 document.getElementById('risk-monthly').innerHTML=riskData.monthly.map(r=>'<tr><td>'+H(r.ym.slice(5)+'/'+(+r.ym.slice(0,4)+543))+'</td>'+['total_births','apgar1_lt7','apgar5_lt7','apgar10_lt7','lbw','vlbw','elbw','lbw_percent','missing_weight'].map(k=>'<td>'+H(r[k]??'—')+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="10" class="empty">ไม่มีข้อมูลเดือนที่เลือก</td></tr>';
}

function recordedRisk(r){
 const flag=String(val(r,'High Risk (รหัส)')).trim().toUpperCase();
 const detail=String(val(r,'รายการความเสี่ยง ANC')).trim();
 if(flag==='Y')return {kind:'flagged',label:'มีความเสี่ยง',detail:detail||'บันทึก High Risk = Y'};
 if(detail&&detail!=='ไม่มี')return {kind:'review',label:'ตรวจสอบรายการความเสี่ยง',detail};
 return {kind:'none',label:flag==='N'?'ไม่ติดธงความเสี่ยง':'ยังไม่ระบุความเสี่ยง',detail:''};
}
function riskBadge(r){const risk=recordedRisk(r);return risk.kind==='none'?'':`<span class="risk-badge risk-${risk.kind}" title="${H(risk.detail)}">⚠ ${risk.label}</span>`}

function renderEmrQueue(){
 document.getElementById('emr-history-scope').textContent=detailData===DATA?'เฉพาะผู้รับบริการรายนี้ในขอบเขตที่เลือก':'เฉพาะผู้รับบริการรายนี้ในผลค้นหา';
 const current=detailData.main[activeCase];
 const hn=String(val(current,'HN มารดา')).trim();
 const rows=detailData.main.map((r,i)=>({r,i}))
  .filter(({r})=>current&&(r===current||(hn!==''&&String(val(r,'HN มารดา')).trim()===hn)))
  .sort((a,b)=>admitDate(b.r).localeCompare(admitDate(a.r)));
 document.getElementById('emr-queue-count').textContent=rows.length;
 document.getElementById('emr-patients').innerHTML=rows.map(({r,i})=>`<button type="button" class="emr-patient risk-${recordedRisk(r).kind} ${i===activeCase?'selected':''}" aria-pressed="${i===activeCase}" onclick="setCase(${i})"><strong>รับไว้รักษา ${H(formatThaiInput(admitDate(r))||admitDate(r)||'—')}</strong>${riskBadge(r)}<small>AN ${H(val(r,'AN มารดา')||'—')}</small><span class="pill">${r._infant_id===null?'ยังไม่มีระเบียนทารก':'ทารก '+H(val(r,'ลำดับทารก')||'—')}</span>${Object.keys(manualDrafts[r._record_id]||{}).length?'<span class="pill warn">ยังไม่บันทึก</span>':''}</button>`).join('')||'<div class="empty">ไม่พบรายการ</div>';
}
function emrText(r,key,unit=''){const value=fieldDisplayValue(r,key);return value===''?'ไม่ระบุ':H(value)+(unit?' '+unit:'')}
function renderEmrHeader(r){
 const risk=r?recordedRisk(r):{kind:'none'};
 const banner=document.getElementById('emr-risk-banner');
 banner.className=risk.kind==='none'?'':'emr-risk-banner risk-'+risk.kind;
 banner.innerHTML=risk.kind==='none'?'':riskBadge(r)+'<div>'+H(risk.detail)+'</div><small>แหล่งข้อมูล: '+(r._manual?.['High Risk (รหัส)']||r._manual?.['รายการความเสี่ยง ANC']?'ข้อมูลกรอกเพิ่มเติม':'ทะเบียน ANC ใน HOSxP')+'</small>';

 document.getElementById('emr-demographics').innerHTML=r?[['HN มารดา','HN มารดา'],['AN มารดา','AN มารดา'],['อายุ','อายุมารดา ณ วันคลอด'],['วันที่ Admit','วันที่ Admit'],['หอผู้ป่วย','หอผู้ป่วย'],['สิทธิการรักษา','สิทธิการรักษา']].map(([label,key])=>`<div><small>${label}</small><b>${emrText(r,key,key==='อายุมารดา ณ วันคลอด'?'ปี':'')}</b></div>`).join(''):'';
 const vitals=[['GA เมื่อคลอด','GA สัปดาห์','สัปดาห์'],['น้ำหนักทารก','น้ำหนักทารก กรัม','กรัม'],['APGAR นาทีที่ 5','APGAR 5 นาที','/ 10'],['วันที่ / เวลาเกิด','วันที่คลอด','']];
 document.getElementById('emr-vitals').innerHTML=r?vitals.map(([label,key,unit])=>`<div class="emr-vital"><small>${label}</small><b>${key==='วันที่คลอด'?emrText(r,key)+'<br><small>เวลาเกิด '+emrText(r,'เวลาคลอด')+'</small>':(key==='GA สัปดาห์'?emrText(r,key)+' สัปดาห์'+(val(r,'GA วัน')!==''?' '+emrText(r,'GA วัน')+' วัน':''):emrText(r,key,unit))}</b><span>${r._manual?.[key]?'ข้อมูลกรอกเพิ่มเติม':'ข้อมูล HOSxP'}</span></div>`).join(''):'';
 document.getElementById('case-status').textContent=r?((r._infant_id===null?'ทะเบียนมารดา':'ทารกลำดับ '+(val(r,'ลำดับทารก')||'—'))+' · ข้อมูลเสริม '+Object.keys(r._manual||{}).length+' ช่อง'):'ยังไม่มีข้อมูล';
 document.getElementById('emr-section-title').textContent=emrTabTitles[activeTab];
}

function labFlags(row){
 const critical=String(val(row,'วิกฤต (รหัส)')).toUpperCase()==='Y',abnormal=String(val(row,'ผิดปกติ (รหัส)')).toUpperCase()==='Y';
 return (critical?'<span class="pill red">⚠ วิกฤต (HOSxP)</span>':'')+(abnormal?'<span class="pill warn">ผลติดธงผิดปกติ</span>':'')||'<span class="mini">ไม่ติดธง / ไม่ระบุ</span>';
}
function labDate(row,dateKey,timeKey){const d=val(row,dateKey);return d&&d!=='0000-00-00'?H(formatThaiInput(String(d).slice(0,10))||d)+'<br><small class="mini">'+H(val(row,timeKey))+'</small>':'<span class="muted">ไม่ระบุ</span>'}
function labResultTable(rows,withMother=false){
 const columns=['รหัส Lab','แบบฟอร์ม','แหล่งใบสั่ง','วันที่รับสิ่งส่งตรวจ','เวลารับสิ่งส่งตรวจ','วันที่รายงาน','เวลารายงาน','ผู้รายงาน','แหล่งค่าอ้างอิง','ยืนยันผล (รหัส)','ยืนยันรายงาน (รหัส)','สถานะผล (รหัส)','สิ่งส่งตรวจ (รหัส)','หมายเหตุผล','หมายเหตุใบสั่ง'];
 return '<div class="tablewrap"><table class="tbl detailed-labs"><thead><tr>'+(withMother?'<th>AN / HN มารดา</th>':'')+'<th>วันเวลาสั่ง</th><th>ใบสั่ง</th><th>รายการตรวจ</th><th>ผลตรวจ / หน่วย</th><th>ค่าอ้างอิง</th><th>ธง / การยืนยัน</th><th>รายละเอียด</th></tr></thead><tbody>'+rows.map(row=>{
 const critical=String(val(row,'วิกฤต (รหัส)')).toUpperCase()==='Y',abnormal=String(val(row,'ผิดปกติ (รหัส)')).toUpperCase()==='Y';
 return '<tr class="'+(critical?'lab-critical':abnormal?'lab-abnormal':'')+'">'+(withMother?'<td>'+display(row,'AN มารดา')+'<br><small class="mini">HN '+H(val(row,'HN มารดา'))+'</small></td>':'')+'<td>'+labDate(row,'วันที่สั่ง','เวลาสั่ง')+'</td><td>'+display(row,'เลขใบสั่ง Lab')+'<br><small class="mini">'+H(val(row,'แหล่งใบสั่ง'))+'</small></td><td>'+display(row,'ชื่อรายการ')+'<br><small class="mini">รหัส '+H(val(row,'รหัส Lab'))+'</small></td><td class="lab-result-value">'+(String(val(row,'ผลตรวจ')).trim()!==''?display(row,'ผลตรวจ'):'<span class="muted">ยังไม่มีผล</span>')+' <small>'+H(val(row,'หน่วย'))+'</small></td><td>'+display(row,'ค่าอ้างอิง')+'<br><small class="mini">'+H(val(row,'แหล่งค่าอ้างอิง'))+'</small></td><td>'+labFlags(row)+'<br><small class="mini">'+(String(val(row,'ยืนยันผล (รหัส)')).toUpperCase()==='Y'?'ยืนยันผลแล้ว':'ยังไม่ยืนยัน / ไม่ระบุ')+'</small></td><td><details class="lab-details"><summary>ดูรายละเอียด</summary><dl>'+columns.map(k=>'<dt>'+H(k)+'</dt><dd>'+display(row,k)+'</dd>').join('')+'</dl></details></td></tr>'
 }).join('')+'</tbody></table>'+(rows.length?'':'<div class="empty">ไม่พบผล Lab ในขอบเขตนี้</div>')+'</div>';
}
function labourLabTable(rows,withMother=false){const columns=(withMother?['AN มารดา','HN มารดา']:[]).concat(['ชื่อรายการ','รหัส Lab','ผล Lab 1','ผล Lab 2','หน่วย','ค่าอ้างอิง','ค่าที่เลือกได้']);return '<div class="tablewrap"><table class="tbl detailed-labs"><thead><tr>'+columns.map(k=>'<th>'+H(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+columns.map(k=>'<td>'+display(r,k)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'+(rows.length?'':'<div class="empty">ไม่พบข้อมูลในทะเบียนห้องคลอด</div>')+'</div>'}
function labPanel(title,rows,html){return '<div class="panel lab-panel"><div class="ph"><h3>'+title+' <span class="pill">'+rows.length+' รายการ</span></h3></div>'+html+'</div>'}
let selectedLabAn=null,labPatientRows=[];
function changeLabPeriod(){
 const from=document.getElementById('lab-period-from').value,to=document.getElementById('lab-period-to').value;
 if(!from||!to||to<from||(Date.parse(to)-Date.parse(from))/86400000>370){alert('กรุณาเลือกช่วงวันที่ให้ถูกต้อง ไม่เกิน 370 วัน');return}
 document.getElementById('from').value=from;document.getElementById('to').value=to;syncThaiDateInputs();selectedLabAn=null;loadLive();
}
function groupLabPatients(data){
 const groups=new Map();
 for(const row of data.main){const an=String(val(row,'AN มารดา'));if(an&&!groups.has(an))groups.set(an,{an,row,hospital:[],labour:[]})}
 for(const [key,target] of [['lab_results','hospital'],['labs','labour']])for(const row of data[key]){const group=groups.get(String(val(row,'AN มารดา')));if(group)group[target].push(row)}
 return [...groups.values()];
}
function openLabPatient(index){selectedLabAn=labPatientRows[index]?.an??null;renderLabPage()}
function closeLabPatient(){selectedLabAn=null;renderLabPage()}
function renderLabPage(){
 document.getElementById('lab-period-from').value=document.getElementById('from').value;
 document.getElementById('lab-period-to').value=document.getElementById('to').value;
 const q=(document.getElementById('lab-search').value||'').trim().toLowerCase(),kind=document.getElementById('lab-kind').value;
 const groups=groupLabPatients(DATA);
 labPatientRows=groups.filter(g=>{const results=kind==='hospital'?g.hospital:kind==='labour'?g.labour:g.hospital.concat(g.labour);return (kind==='all'||results.length>0)&&(!q||[g.row,...results].some(r=>Object.entries(r).some(([k,v])=>!k.startsWith('_')&&String(v??'').toLowerCase().includes(q))))});
 const selected=groups.find(g=>g.an===selectedLabAn);if(!selected)selectedLabAn=null;
 document.getElementById('lab-total').textContent=labPatientRows.length+' AN';
 document.getElementById('lab-patient-list').hidden=!!selected;
 document.getElementById('lab-patient-list').innerHTML='<div class="panel"><div class="tablewrap"><table class="tbl"><thead><tr><th>วันที่ Admit</th><th>AN มารดา</th><th>HN มารดา</th><th>ชื่อ-สกุลมารดา</th><th>ห้องปฏิบัติการ</th><th>ทะเบียนคลอด</th><th>รายละเอียด</th></tr></thead><tbody>'+labPatientRows.map((g,i)=>'<tr class="lab-patient-row" onclick="openLabPatient('+i+')"><td>'+display(g.row,'วันที่ Admit')+'</td><td>'+H(g.an)+'</td><td>'+display(g.row,'HN มารดา')+'</td><td>'+display(g.row,'ชื่อ-สกุลมารดา')+'</td><td>'+g.hospital.length+' รายการ</td><td>'+g.labour.length+' รายการ</td><td><button type="button" class="btn small ghost" onclick="event.stopPropagation();openLabPatient('+i+')">ดูผลตรวจ</button></td></tr>').join('')+(labPatientRows.length?'':'<tr><td colspan="7" class="empty">ไม่พบรายชื่อในช่วงวันที่หรือคำค้นที่เลือก</td></tr>')+'</tbody></table></div></div>';
 document.getElementById('lab-patient-detail').innerHTML=selected?'<div class="headline"><div><h3>'+H(val(selected.row,'ชื่อ-สกุลมารดา'))+'</h3><div class="muted">AN '+H(selected.an)+' · HN '+H(val(selected.row,'HN มารดา'))+' · Admit '+H(val(selected.row,'วันที่ Admit'))+'</div></div><button type="button" class="btn" onclick="closeLabPatient()">← กลับรายชื่อ</button></div>':'';
 document.getElementById('lab-results-container').innerHTML=!selected||kind==='labour'?'':labPanel('ผลจากห้องปฏิบัติการ',selected.hospital,labResultTable(selected.hospital));
 document.getElementById('lab-labour-container').innerHTML=!selected||kind==='hospital'?'':labPanel('ผลในทะเบียนห้องคลอด',selected.labour,labourLabTable(selected.labour));
}

function renderEmrRelated(r,kind='labs'){
 const an=String(val(r,'AN มารดา'));
 const sets=[['ภาวะแทรกซ้อน','complications',['รหัสภาวะแทรกซ้อน','รหัสระยะคลอด','รายละเอียด']],['วัคซีน','vaccines',['รหัสวัคซีน','Lot','วันหมดอายุ','รหัสผู้ให้']]];
 const hospital=detailData.lab_results.filter(x=>String(val(x,'AN มารดา'))===an),labour=detailData.labs.filter(x=>String(val(x,'AN มารดา'))===an);
 const labContent='<div class="note">ผล Lab มารดา AN '+H(an)+' · ใบสั่งผูกกับ AN หรือ VN ตอน Admit ของมารดาเท่านั้น ไม่รวมผลทารก หน่วยอ้างอิงจากรายการปัจจุบัน</div>'+labPanel('ผลจากห้องปฏิบัติการ',hospital,labResultTable(hospital))+labPanel('ผลในทะเบียนห้องคลอด',labour,labourLabTable(labour));
 return (kind==='labs'?labContent:'')+sets.filter(([,key])=>kind==='complications'?key==='complications':key!=='complications').map(([title,key,columns])=>{const rows=detailData[key].filter(x=>String(val(x,'AN มารดา'))===an);return `<div class="emr-linked"><h4>${title} <span class="pill">${rows.length}</span></h4><div class="tablewrap"><table class="tbl"><thead><tr>${columns.map(c=>'<th>'+H(c)+'</th>').join('')}</tr></thead><tbody>${rows.map(x=>'<tr>'+columns.map(c=>'<td>'+display(x,c)+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="'+columns.length+'" class="empty">ไม่พบข้อมูลใน HOSxP</td></tr>'}</tbody></table></div></div>`}).join('');
}

async function recordUsage(event,details={}){
 try{const res=await fetch('usage.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:JSON.stringify({event,...details}),keepalive:true});return res.ok}catch{return false}
}
function setCase(i){const record=detailData.main[i];if(record)recordUsage('record_open',{record_id:record._record_id});activeCase=Math.min(Math.max(0,i),Math.max(0,detailData.main.length-1));renderDetail()}function openCase(i,searching=false){detailData=searching?registrySearchData:DATA;activeCase=i;activeTab=0;const record=detailData?.main[i];if(record)recordUsage('record_open',{record_id:record._record_id});go('detail')}function switchTab(i){activeTab=i;renderDetail()}
let providerList=[],providerLoaded=false,providerLoading=false,providerError='';
function providerLabel(p){return p.name+' ['+p.code+']'}
async function loadDeliveryProviders(){
 if(providerLoading)return;providerLoading=true;providerError='';
 try{const res=await fetch('api.php?lookup=providers',{credentials:'same-origin',cache:'no-store'});const data=await res.json();if(!res.ok||!data.ok)throw Error(data.error||'โหลดรายชื่อไม่สำเร็จ');providerList=data.providers.filter(p=>p.active==='Y');providerLoaded=true;}
 catch(error){providerError=error.message}finally{providerLoading=false;if(currentPage==='detail')renderDetail()}
}
function deliveryProviderControl(r,index,value,disabled){
 if(!providerLoaded&&!providerLoading&&!providerError)loadDeliveryProviders();
 const draft=manualDrafts[r._record_id]||{},code=Object.hasOwn(draft,'รหัสผู้ทำคลอด (ทารก)')?draft['รหัสผู้ทำคลอด (ทารก)']:val(r,'รหัสผู้ทำคลอด (ทารก)');
 const selected=providerList.find(p=>p.code===String(code));const text=selected?providerLabel(selected):value;
 return `<input id="emr-field-${index}" class="input manual-input provider-input" data-field="${index}" type="search" list="delivery-provider-options" autocomplete="off" placeholder="พิมพ์ชื่อหรือรหัสแพทย์ / พยาบาล" value="${H(text)}" ${disabled||!providerLoaded?'disabled':''} oninput="chooseDeliveryProvider(this)"><datalist id="delivery-provider-options">${providerList.map(p=>`<option value="${H(providerLabel(p))}" label="${H(p.role)} · Active"></option>`).join('')}</datalist><small class="mini">${providerError?H(providerError):providerLoaded?'แพทย์และพยาบาล Active '+providerList.length+' ราย · พิมพ์ค้นหาแล้วเลือกชื่อ':'กำลังโหลดรายชื่อ HOSxP…'}</small>${providerError?'<button type="button" class="btn small" onclick="loadDeliveryProviders()">ลองโหลดรายชื่ออีกครั้ง</button>':''}`;
}
function chooseDeliveryProvider(input){
 const row=detailData.main[activeCase];if(!row)return;const text=input.value.trim();
 const matches=providerList.filter(p=>providerLabel(p)===text||p.code===text);
 input.setCustomValidity(text&&matches.length!==1?'กรุณาเลือกชื่อพร้อมรหัสจากรายการ HOSxP':'');
 if(text&&matches.length!==1)return;
 const draft=manualDrafts[row._record_id]??={};draft['รหัสผู้ทำคลอด (ทารก)']=text?matches[0].code:'';draft['ชื่อผู้ทำคลอด']=text?matches[0].name:'';
 document.getElementById('manual-message').textContent='มีข้อมูลที่ยังไม่บันทึก';renderEmrQueue();
}


function organizeReviewedFields(area){
 const fields=[...area.querySelectorAll('[data-label]')];
 const find=label=>fields.find(el=>el.dataset.label===label);
 if(activeTab===1){
  const grid=area.querySelector('.fgrid');
  const groups=[
   ['ประวัติการตั้งครรภ์',['G','TP','Pre','A','L','LMP','EDC','GA สัปดาห์','GA วัน']],
   ['ฝากครรภ์ครั้งแรก / ประวัติ ANC',['วันที่ฝากครรภ์ครั้งแรก','GA ฝากครรภ์ครั้งแรก สัปดาห์','GA ฝากครรภ์ครั้งแรก วัน','จำนวนครั้ง ANC','สถานที่ ANC','ประเภท ANC']],
   ['ข้อมูลสามีและผลเลือด',['ชื่อสามี','Hb typing บิดา','DCIP บิดา','ผล HIV บิดา (ตามชีต)','ผล VDRL บิดา (ตามชีต)']],
   ['วัคซีน dT',['วัคซีน dT (ตามชีต)']],
   ['ความเสี่ยงครรภ์นี้',['High Risk (รหัส)','รายการความเสี่ยง ANC']]
  ];
  for(const [title,keys] of groups){
   const visible=keys.map(find).filter(Boolean);if(!visible.length)continue;
   const section=document.createElement('section');section.className='wide anc-section';
   const heading=document.createElement('h4');heading.textContent=title;section.append(heading);
   if(title==='ประวัติการตั้งครรภ์'){
    const summary=document.createElement('p');summary.id='pregnancy-summary';summary.className='mini';section.append(summary);
   }
   if(title==='ฝากครรภ์ครั้งแรก / ประวัติ ANC'){
    const hint=document.createElement('p');hint.className='mini';hint.textContent='GA ครั้งแรกแยกจาก GA ปัจจุบัน · จำนวนครั้ง ANC คือจำนวนครั้งฝากครรภ์ทั้งหมด';section.append(hint);
   }
   const body=document.createElement('div');body.className='fgrid';visible.forEach(el=>body.append(el));section.append(body);grid.append(section);
  }
  updatePregnancySummary();
 }
 if(activeTab===3){
  const table=document.createElement('div');table.className='wide tablewrap';
  table.innerHTML='<table class="tbl"><caption>APGAR แยก 5 ด้าน นาทีที่ 1–5–10</caption><thead><tr><th>นาที</th>'+['HR','RR','Reflex','Tone','Color','รวม'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody></tbody></table>';
  area.querySelector('.fgrid').prepend(table);
  for(const minute of [1,5,10]){const tr=document.createElement('tr');tr.innerHTML='<th>'+minute+'</th>';for(const part of ['hr','rr','reflex','tone','color','']){const td=document.createElement('td');const el=find('APGAR '+minute+' นาที'+(part?' '+part:''));if(el){el.querySelector('label').classList.add('hide');const input=el.querySelector('input');if(input){input.max=part?'2':'10';input.step='1';input.style.width='80px'}td.append(el)}tr.append(td)}table.querySelector('tbody').append(tr)}
 }
}
function updatePregnancySummary(){
