 const row=detailData.main[activeCase],draft=manualDrafts[row._record_id]||{};
 const value=key=>{const v=Object.hasOwn(draft,key)?draft[key]:reviewedFieldValue(row,key);return v===''?'?':String(v)};
 summary.textContent='G'+value('G')+' P'+['TP','Pre','A','L'].map(value).join(' / ')+' · P เรียง TP / Pre / A / L · ? = ยังไม่ระบุ';
}
function reviewedFieldValue(row,key){
 const value=val(row,key),field=FIELD_CATALOG.find(f=>f.label===key);
 return value===''&&row._labour_id!=null&&field?.hosxpNullZero?'0':value;
}

