  const disabled=manualSaving.has(r._record_id)||r._supplement_available===false||(f.checkbox&&!editable)?'disabled':'';
  const control=f.checkbox?`<div class="rowflex"><input id="emr-field-${index}" class="manual-input" data-field="${index}" type="checkbox" value="${H(value)}" ${String(value).toUpperCase()==='Y'?'checked':''} ${disabled} onchange="this.value=this.checked?'Y':'N';this.parentElement.querySelector('small').textContent=this.checked?'':'ไม่ได้ให้';this.dispatchEvent(new Event('input'))"><span>ให้แล้ว</span><small>${value===''?'ยังไม่ระบุ':value==='N'?'ไม่ได้ให้':''}</small><button type="button" class="btn small" ${disabled} onclick="const el=document.getElementById('emr-field-${index}');el.checked=false;el.value='';el.parentElement.querySelector('small').textContent='ยังไม่ระบุ';el.dispatchEvent(new Event('input'))">ล้างค่า</button></div>`:f.provider?deliveryProviderControl(r,index,value,disabled):Array.isArray(f.options)?`<select id="emr-field-${index}" class="input manual-input" ${disabled} data-field="${index}"><option value="">— ยังไม่ระบุ —</option>${legacy?`<option value="${H(savedValue)}" ${String(value)===String(savedValue)?'selected':''}>${H(savedValue)} (ค่าเดิม)</option>`:''}${f.options.map(option=>`<option value="${H(option)}" ${String(value)===option?'selected':''}>${H(option)}</option>`).join('')}</select>`:`<input id="emr-field-${index}" class="input manual-input" ${disabled} data-field="${index}" type="${['number','date','time'].includes(f.type)?f.type:'text'}" ${f.type==='number'?(f.editable===true?'min="0" max="999" step="1"':'min="0" step="any"'):''} ${f.type==='time'?'step="60"':''} maxlength="2000" value="${H(f.type==='time'?String(value).slice(0,5):value)}">`;

  const sourceNote=f.editable===true&&r._source?.[f.label]!==undefined?' • HOSxP เดิม: '+(r._source[f.label]??'ไม่ระบุ'):'';
  const nullZero=f.hosxpNullZero&&r._labour_id!=null&&val(r,f.label)===''&&!Object.hasOwn(draft,f.label);
