  return `<div data-label="${H(f.label)}" class="field ${['High Risk (รหัส)','รายการความเสี่ยง ANC'].includes(f.label)&&recordedRisk(r).kind!=='none'?'risk-field':''}"><label for="emr-field-${index}">${H(f.label==='GA สัปดาห์'?'GA เมื่อคลอด สัปดาห์':f.label==='GA วัน'?'GA เมื่อคลอด วัน':f.label)}</label>${f.checkbox||editable||(r._supplement_available===false&&f.editable===true&&Array.isArray(f.options))?control:`<div class="value">${display(r,f.label)}</div>`}<small class="mini">${H(note)}</small></div>`;
 }).join('')+'</div><div class="emr-savebar"><div><strong>บันทึกข้อมูลเพิ่มเติม</strong><small>เก็บแยกจากเวชระเบียน HOSxP</small></div><button class="btn primary" id="save-manual" '+(manualSaving.has(r._record_id)||r._supplement_available===false?'disabled':'')+' onclick="saveManual()">บันทึกข้อมูลเสริม</button><span id="manual-message" role="status" class="mini" style="margin-left:12px">'+(Object.keys(draft).length?'มีข้อมูลที่ยังไม่บันทึก':'')+'</span></div>';
 organizeReviewedFields(area);
