}
async function saveManual(){
 const savedData=detailData,r=savedData.main[activeCase],id=r?._record_id;if(!id)return;if(r._supplement_available===false){alert('กรุณาโหลดข้อมูลเสริมให้สำเร็จก่อนบันทึก');return}
 const providerInput=document.querySelector('.provider-input');if(providerInput&&!providerInput.reportValidity())return;
 const fields={...manualDrafts[id]};if(!Object.keys(fields).length){document.getElementById('manual-message').textContent='ไม่มีข้อมูลเปลี่ยนแปลง';return}
 if(manualSaving.has(id))return;manualSaving.add(id);renderDetail();
 const btn=document.getElementById('save-manual');btn.disabled=true;
 try{
  const res=await fetch('manual.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:JSON.stringify({id,version:r._version,fields})});
  const payload=await res.json();if(res.status===401){window.location.href='login.php';return}if(!res.ok||!payload.ok)throw Error(payload.error||'บันทึกไม่สำเร็จ');
  for(const source of new Set([DATA,savedData,detailData,registrySearchData])){
   const index=source?.main.findIndex(row=>row._record_id===id)??-1;
   if(index<0)continue;
   const oldRow=source.main[index];
   source.main[index]=Object.hasOwn(oldRow,'ลำดับรายงาน')?{...payload.row,'ลำดับรายงาน':oldRow['ลำดับรายงาน']}:payload.row;
  }
  delete manualDrafts[id];manualSaving.delete(id);renderAll();
  if(detailData.main[activeCase]?._record_id===id&&document.getElementById('manual-message'))document.getElementById('manual-message').textContent='บันทึกแล้ว';
 }catch(err){if(detailData.main[activeCase]?._record_id===id&&document.getElementById('manual-message'))document.getElementById('manual-message').textContent=err.message;}finally{manualSaving.delete(id);btn.disabled=false;if(detailData.main[activeCase]?._record_id===id){document.querySelectorAll('.manual-input').forEach(input=>input.disabled=false);const currentButton=document.getElementById('save-manual');if(currentButton)currentButton.disabled=false}}
}
window.addEventListener('beforeunload',event=>{if(Object.values(manualDrafts).some(d=>Object.keys(d).length)){event.preventDefault();event.returnValue=''}});
