 const buttons=[...document.querySelectorAll('button[onclick^="exportExcel"],button[onclick^="exportSelected"]')];buttons.forEach(b=>b.disabled=true);
 const status=document.getElementById('registry-search-status');const label={xlsx:'Excel',csv:'CSV ทะเบียน',csvzip:'CSV ครบ 10 หมวด'}[format];status.textContent='กำลังจัดทำ '+label+'…';
 try{
  const res=await fetch(reportOutputUrl(format,all),{method:'POST',credentials:'same-origin',body:new URLSearchParams({csrf:csrfToken})});
  if(!res.ok||!(res.headers.get('Content-Type')||'').includes({xlsx:'spreadsheetml',csv:'text/csv',csvzip:'application/zip'}[format])){const error=await res.json().catch(()=>({}));throw new Error(error.error||'ส่งออกไม่สำเร็จ กรุณาลองใหม่หรือเลือกช่วงวันที่ให้แคบลง')}
  const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='LR_all_fields_'+(all?'all':document.getElementById('from').value+'_'+document.getElementById('to').value)+'.'+(format==='csvzip'?'zip':format);a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='จัดทำ '+label+' สำเร็จ · '+(all?'ผู้รับบริการทั้งหมดทุกช่วงเวลา':'ตามช่วงวันที่ Admit');
 }catch(err){status.textContent=err.message;alert(err.message)}finally{window.excelExportBusy=false;buttons.forEach(b=>b.disabled=false)}
}
