 const r=detailData.main[activeCase];if(!r){alert('กรุณาเลือกผู้ป่วยก่อนพิมพ์');return}
 if(Object.values(manualDrafts).some(d=>Object.keys(d).length)){alert('กรุณาบันทึกข้อมูลที่แก้ไขก่อนพิมพ์');return}
