function csvCell(value){let text=(Array.isArray(value)?JSON.stringify(value):String(value??''));if(/^[\s\uFEFF]*[=+@-]/.test(text)||/^[\t\r\n]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}
async function exportCSV(){let rows=registryRows();if(!rows.length){alert('ไม่มีข้อมูลให้ส่งออก');return}if(!await recordUsage('csv_export',{count:rows.length})){alert('บันทึกประวัติการส่งออกไม่สำเร็จ กรุณาลองใหม่');return}let headers=[...new Set([...FIELD_CATALOG.map(f=>f.label),...rows.flatMap(x=>Object.keys(x).filter(k=>!k.startsWith('_')))])];let csv='\uFEFF'+[headers,...rows.map(r=>headers.map(k=>r[k]??''))].map(a=>a.map(csvCell).join(',')).join('\r\n');let blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='LR_export_'+(new Date().toISOString().slice(0,10))+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let liveRequestId=0;
async function loadLive(){
  const requestId=++liveRequestId;
  const previousRecord=detailData.main[activeCase]?._record_id;
  DATA.newborns=[];
  DATA.newborn_admissions=null;
  for(const k of ['main','labs','complications','vaccines','lab_results'])DATA[k]=[];
  renderAll();
  const from=document.getElementById('from').value,to=document.getElementById('to').value;
  const msg=document.getElementById('import-msg');
  const notice=document.getElementById('live-status');
  if(notice){notice.textContent='กำลังดึงข้อมูล HOSxP…';notice.style.color='#9e6d27'}
  if(msg)msg.textContent='กำลังอ่านข้อมูลจริงจาก HOSxP…';
  try{
    const res=await fetch('api.php?from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to)+'&scope='+'period',{credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}});
    const payload=await res.json();
    if(res.status===401){window.location.href='login.php';return}
    if(requestId!==liveRequestId)return;
    if(!res.ok || !payload.ok)throw Error(payload.error||'HTTP '+res.status);
    DATA.newborns=payload.data.newborns||[];
    DATA.newborn_admissions=Number.isInteger(payload.data.newborn_admissions)?payload.data.newborn_admissions:null;
    csrfToken=payload.csrf;
    for(const k of ['main','labs','complications','vaccines','lab_results']) DATA[k]=payload.data[k]||[];
    if(detailData===DATA)activeCase=Math.max(0,DATA.main.findIndex(r=>r._record_id===previousRecord));imported=true;renderAll();if(document.getElementById('emr-scope').value==='ward')changeEmrScope();
    const when=new Date().toLocaleString('th-TH');
    if(notice){notice.textContent=`● เชื่อมต่อ HOSxP สำเร็จ • ${when} • ${DATA.main.length} รายการ`;notice.style.color='#17877c'}
    if(msg)msg.textContent=`เชื่อมต่อสำเร็จ: ข้อมูลจริง ${DATA.main.length} รายการ ณ ${when}`;
    document.querySelector('.privacy').textContent=(payload.warnings||[]).join(' ')||'ข้อมูลจริงจาก HOSxP • แสดงเฉพาะผู้ได้รับอนุญาต • ห้ามเผยแพร่ข้อมูลระบุตัวบุคคล';
  } catch(err){
    if(requestId!==liveRequestId)return;
    DATA.newborns=[];
  DATA.newborn_admissions=null;
  for(const k of ['main','labs','complications','vaccines','lab_results'])DATA[k]=[];
    renderAll();
    if(notice){notice.textContent='● เชื่อมต่อไม่สำเร็จ: '+err.message;notice.style.color='#b94a5e'}
    if(msg)msg.textContent='ไม่สามารถเชื่อมต่อ HOSxP: '+err.message;
  }
}
document.querySelectorAll('#detail [role="tab"]').forEach((tab,index)=>{
 tab.addEventListener('keydown',event=>{
  if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;
  event.preventDefault();
  const next=event.key==='Home'?0:event.key==='End'?5:(index+(event.key==='ArrowRight'?1:5))%6;
  switchTab(next);document.querySelectorAll('#detail [role="tab"]')[next].focus();
 });
});

function setSidebarCollapsed(collapsed){
 document.querySelector('.shell').classList.toggle('sidebar-collapsed',collapsed);
 const button=document.getElementById('sidebar-toggle');
 button.textContent=collapsed?'›':'‹';button.setAttribute('aria-expanded',String(!collapsed));
 const label=collapsed?'ขยายเมนูด้านข้าง':'ยุบเมนูด้านข้าง';button.setAttribute('aria-label',label);button.title=label;
 document.querySelectorAll('.nav').forEach(nav=>{const name=nav.querySelector('.nav-label')?.textContent||'';nav.title=name;nav.setAttribute('aria-label',name)});
 try{localStorage.setItem('lr-sidebar-collapsed',String(collapsed))}catch{}
}
function toggleSidebar(){setSidebarCollapsed(!document.querySelector('.shell').classList.contains('sidebar-collapsed'))}
try{setSidebarCollapsed(localStorage.getItem('lr-sidebar-collapsed')==='true')}catch{setSidebarCollapsed(false)}

setTodayDates();
syncThaiDateInputs();
go('dashboard');
loadLive();
</script></body></html>
